import{_ as l}from"./chunks/28.Cz-DdexM.js";import{_ as d}from"./chunks/1._Wu06lVH.js";import{_ as t}from"./chunks/0.xVPDiwtD.js";import{_ as c}from"./chunks/2.9ug2zROR.js";import{_ as h}from"./chunks/3.Bpl7qdog.js";import{_ as g}from"./chunks/5.El-v_jQk.js";import{_ as p}from"./chunks/6.D84Ot_V6.js";import{_ as m}from"./chunks/11.DiIhyeL-.js";import{_ as a}from"./chunks/0.B7TrDeTt.js";import{_ as u}from"./chunks/12.D1pIPcbk.js";import{_ as y}from"./chunks/1.BU1qyW7B.js";import{_ as i}from"./chunks/0.DyB7G7H5.js";import{_}from"./chunks/3.PcdR27wg.js";import{_ as f}from"./chunks/9._7FszrLL.js";import{_ as o}from"./chunks/0.C_OEUMPL.js";import{_ as b}from"./chunks/11.DPtnPYcq.js";import{_ as w}from"./chunks/100.DMbJtyMU.js";import{_ as x}from"./chunks/community.BdKwbEUF.js";import{_ as k,C as v,o as z,c as P,ak as r,E as q}from"./chunks/framework.sbZkgmEx.js";const B="/projects/AiBlock/en/advanced-kit/assets/1.DG_9uIbf.webp",T="/projects/AiBlock/en/advanced-kit/assets/2.1.spV0OpNX.webp",n="/projects/AiBlock/en/advanced-kit/assets/2.1.BAk-fKUi.webp",A="/projects/AiBlock/en/advanced-kit/assets/3.DV8fDUrs.webp",C="/projects/AiBlock/en/advanced-kit/assets/4.C0Jtkh4D.webp",it=JSON.parse('{"title":"3.28 Patrol Helicopter","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.28 Patrol Helicopter.md","filePath":"docs/3.Creative Builds/3.28 Patrol Helicopter.md"}'),j={name:"docs/3.Creative Builds/3.28 Patrol Helicopter.md"};function S(R,e,G,D,H,I){const s=v("Pdf");return z(),P("div",null,[e[0]||(e[0]=r('<h1 id="_3-28-patrol-helicopter" tabindex="-1">3.28 Patrol Helicopter <a class="header-anchor" href="#_3-28-patrol-helicopter" aria-label="Permalink to &quot;3.28 Patrol Helicopter&quot;">​</a></h1><h2 id="_3-28-1-lesson-introduction" tabindex="-1">3.28.1 Lesson Introduction <a class="header-anchor" href="#_3-28-1-lesson-introduction" aria-label="Permalink to &quot;3.28.1 Lesson Introduction&quot;">​</a></h2><p>Centering on the military patrol helicopter model, this lesson explores coordinated programming across the drive motor, ultrasonic sensor, buzzer, and RGB light module. It implements an automated security patrol routine that spins the rotor blades and sounds an audiovisual alert upon obstacle detection. The content examines aerodynamic rotor lift and propeller drivetrains, covers motor speed regulation, and applies sensor-triggered multi-actuator synchronization logic to demonstrate integrated audiovisual interaction.</p><img loading="lazy" height="1662" width="1662" src="'+l+'" class="common_img" style="width:400px;"><h2 id="_3-28-2-learning-objectives" tabindex="-1">3.28.2 Learning Objectives <a class="header-anchor" href="#_3-28-2-learning-objectives" aria-label="Permalink to &quot;3.28.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand aerodynamic lift generated by rotating helicopter rotors. Master control logic for triggering audiovisual alarms via ultrasonic obstacle detection. Recognize the operating characteristics of RGB breathing modes and non-blocking background buzzer playback.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical airframe of the patrol helicopter independently. Program motor routines to drive propeller rotation. Implement complete system functionality uniting obstacle detection, rotor activation, RGB breathing lights, and buzzer alerts.</p></li><li><p><strong>Thinking Objectives</strong>: Establish single-trigger multi-response control logic where one condition drives multiple actuators simultaneously. Cultivate interactive design awareness for integrated audiovisual systems. Strengthen understanding of aerospace mechanics combined with electronic automation.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to surveillance drones, autonomous helicopters, and automated perimeter alarms. Understand the critical role of rotorcraft across military reconnaissance and disaster relief missions. Stimulate interest in aeronautical engineering and unmanned aerial vehicle technology.</p></li></ol><h2 id="_3-28-3-preparation" tabindex="-1">3.28.3 Preparation <a class="header-anchor" href="#_3-28-3-preparation" aria-label="Permalink to &quot;3.28.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>Ultrasonic sensor</p></li><li><p>RGB light module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-28-4-hands-on-project" tabindex="-1">3.28.4 Hands-On Project <a class="header-anchor" href="#_3-28-4-hands-on-project" aria-label="Permalink to &quot;3.28.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Patrol Helicopter, delivering an automated surveillance aircraft that sounds a synchronized alarm upon spotting targets. The system adopts an ultrasonic detection and multi-module audiovisual alert architecture: the ultrasonic sensor continuously scans ahead, triggering an alarm whenever an obstacle is detected within 50 cm. Three subsystems respond simultaneously in the execution phase: the motor spins the main rotor at high speed to simulate an engine spool-up, the RGB light module emits a red breathing fade, and the buzzer sounds a high-pitched siren. The alert holds for 1 s to prevent rapid bouncing between states, and once the target clears, all outputs deactivate to return the helicopter to standby.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),q(s,{src:"../../_static/shared/pdf/chapter_3/28.pdf"}),e[1]||(e[1]=r('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the RGB light module to port <strong>B</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1576" width="2338" src="'+B+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+T+'" class="common_img" style="width:800px;"><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;"><ul><li>Select <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Serves as the main loop container, continuously executing internal code after power-on initialization</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Executes only once after the device powers on, used to place startup logic such as hardware initialization and parameter configuration</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="99" width="982" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Drives the buzzer to play a musical note at a designated pitch and beat in the background without blocking subsequent program execution</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="101" width="439" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Adjusts buzzer volume across a range of 0 to 100, where higher values yield louder audio output</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="99" width="318" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Halts buzzer audio immediately, terminating active tone playback</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="495" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+a+'"></td><td style="text-align:left;">Initializes the port connection for the ultrasonic sensor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="658" src="'+u+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+a+'"></td><td style="text-align:left;">Reads the obstacle distance measured by the ultrasonic sensor on the designated port, in centimeters (cm)</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+y+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+i+'"></td><td style="text-align:left;">Directs the 360° block motor on the designated port to rotate continuously forward or in reverse at a custom speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+_+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+i+'"></td><td style="text-align:left;">Disables output to the 360° block motor on the designated port, halting rotation immediately</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="811" src="'+f+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+o+'"></td><td style="text-align:left;">Directs the RGB light module on the designated port to activate a breathing fade effect in a selected color, with a customizable transition period</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="576" src="'+b+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+o+'"></td><td style="text-align:left;">Extinguishes the RGB light module on the designated port to cut off light output</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="503" width="431" src="'+A+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the ultrasonic sensor interface and sets the buzzer volume to 100. When an obstacle is detected within 50 cm, motor S1 rotates forward at 80% speed to spin the propeller blades, the RGB light module activates breathing mode, and the buzzer sounds note F6. Otherwise, motor S1 halts the rotor and the controller turns off both the RGB light module and the buzzer.</p></li></ul><img loading="lazy" height="700" width="942" src="'+C+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+w+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1KQ-KBn3OmxCo6xKJkb7ZQZAuPW9brr5t?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-28-5-expansion-and-challenge" tabindex="-1">3.28.5 Expansion and Challenge <a class="header-anchor" href="#_3-28-5-expansion-and-challenge" aria-label="Permalink to &quot;3.28.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Tiered Alarm Response System</strong></p><p>Configure a three-tier alert hierarchy: Tier 1 from 30 cm to 50 cm with slow rotor speed, yellow flashing lights, and low-frequency tones, Tier 2 from 15 cm to 30 cm with medium rotor speed, flashing orange lights, and mid-frequency tones, and Tier 3 under 15 cm with maximum rotor speed, rapid red flashing, and high-frequency alarms. Practice multi-threshold partitioning and multi-channel coordinated outputs, extending discussions to security perimeters and airborne collision avoidance systems.</p><p><strong>Project 2: Dual-Rotor Search and Rescue Helicopter</strong></p><p>Integrate a second motor to drive a rescue hoist winch: upon detecting a target, the main rotor spools up while sounding an alert, the winch motor rotates forward to lower a rescue cable, pauses, and reverses to reel it back, while a green RGB light indicates an active rescue mission. Practice controlling dual motors independently and designing sequential routines, extending discussions to search-and-rescue helicopters, heavy-lift drones, and industrial cranes.</p><h2 id="_3-28-6-q-a" tabindex="-1">3.28.6 Q&amp;A <a class="header-anchor" href="#_3-28-6-q-a" aria-label="Permalink to &quot;3.28.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the alarm program incorporate a 1 s delay, and what happens if this delay is omitted?</strong></p><p>Answer: The 1 s dwell interval functions as <strong>software debouncing to prevent erratic alert flickering</strong>. If an obstacle hovers near the 50 cm threshold, minor measurement fluctuations cause sensor readings to oscillate between 49 cm and 51 cm. Without a delay, the system rapidly alternates between triggering and clearing the alert, causing the rotor to stutter, the light to flicker erratically, and the alarm audio to chop. Introducing a 1 s hold ensures that once triggered, the alarm remains active for at least one second regardless of minor sensor fluctuations, producing a steady and cohesive alert response. This represents a standard debouncing or delay-hold technique commonly deployed whenever sensors operate near decision boundaries, exactly like sound-activated hallway lights that remain illuminated for several tens of seconds after a clap rather than switching off immediately.</p><p><strong>Question 2: What is background audio playback, and how does it differ from standard synchronous playback?</strong></p><p>Answer: <strong>Background audio playback</strong> allows the sound engine to play audio non-blockingly without halting subsequent code execution. In standard synchronous playback, the processor halts and waits for an audio tone to finish before advancing to the next instruction: under this mode, an RGB illumination command would have to wait until sound playback concluded, preventing simultaneous audio and lighting output. With non-blocking background playback, the buzzer starts sounding while the controller immediately executes the next RGB lighting command, achieving synchronized audiovisual alarms. This mirrors how a smartphone continues running apps while streaming music in the background. Background playback represents an accessible introduction to multitasking, which in full operating systems expands into multithreading to manage multiple simultaneous operations.</p><h2 id="_3-28-7-technical-support-and-product-discussion" tabindex="-1">3.28.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-28-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.28.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+x+'" class="common_img" style="width:800px;"></a>',33))])}const ot=k(j,[["render",S]]);export{it as __pageData,ot as default};
